//! Rendering a [`Plan`] as proto3 source text.

use crate::shape::{Plan, Shape, Single, classify_field, classify_payload, enum_value_name, field_number, ident};
use novafile_schema::{Def, RecordDef, Schema, VariantDef};
use std::fmt::Write;

/// The `package` of the generated file: the schema name with every
/// non-identifier character replaced by `_`, plus `.v<MAJOR>`.
pub(crate) fn package(schema: &Schema) -> Option<String> {
    let r = schema.reference()?;
    let name: String = r.name.chars().map(|c| if c.is_ascii_alphanumeric() || c == '_' { c } else { '_' }).collect();
    Some(format!("{name}.v{}", r.version.major))
}

/// The name of the `oneof` in a union message: `variant`, unless a variant
/// already uses that name.
pub(crate) fn oneof_name(vs: &[VariantDef]) -> String {
    let mut name = String::from("variant");
    while vs.iter().any(|v| ident(&v.name) == name) {
        name.push('_');
    }

    name
}

/// Render the whole `.proto` file: header comments, `syntax`, `package`,
/// imports, then one definition per entry of the plan.
///
/// # Errors
///
/// Fails if a field or variant has no Protobuf mapping or an invalid field
/// number.
pub(crate) fn render(schema: &Schema, plan: &Plan<'_>) -> Result<String, String> {
    let mut out = String::new();
    let w = &mut out;
    match schema.reference() {
        Some(r) => writeln!(w, "// Generated by novafile-proto from schema {r}."),
        None => writeln!(w, "// Generated by novafile-proto from an anonymous schema."),
    }
    .expect("writing to a String");

    let _ = writeln!(
        w,
        "// Root message: {}. Trailing comments give each field's NOVA type.",
        Single::Message(plan.root).proto_name()
    );
    w.push_str("syntax = \"proto3\";\n");
    if let Some(p) = package(schema) {
        let _ = writeln!(w, "\npackage {p};");
    }

    if !plan.imports.is_empty() {
        w.push('\n');
        for i in &plan.imports {
            let _ = writeln!(w, "import \"{i}\";");
        }
    }

    for (name, def) in &plan.defs {
        w.push('\n');
        match def {
            Def::Record(r) => record(w, schema, name, r)?,
            Def::Enum(vs) if vs.iter().all(|v| v.payload.is_none()) => unit_enum(w, name, vs),
            Def::Enum(vs) => union(w, schema, name, vs)?,
            Def::Alias(_) => unreachable!("aliases are never listed in a plan"),
        }
    }

    Ok(out)
}

/// Write a `message` for a NOVA record. Scalars get explicit presence
/// (`optional`) whenever absence, `null` or a default must stay
/// distinguishable from the zero value.
fn record(w: &mut String, schema: &Schema, name: &str, r: &RecordDef) -> Result<(), String> {
    let _ = writeln!(w, "message {} {{", ident(name));
    for f in &r.fields {
        let number = field_number(name, f)?;
        let c = classify_field(schema, name, f)?;
        let ty = match c.shape {
            // Explicit presence keeps "absent", `null` and "default" apart
            // from the zero value. Message fields always have presence.
            Shape::Single(s @ Single::Scalar(_)) if f.optional || c.nullable || f.default.is_some() => format!("optional {}", s.proto_name()),
            Shape::Single(s) => s.proto_name(),
            Shape::Repeated { elem, .. } => format!("repeated {}", elem.proto_name()),
            Shape::Map { key, value } => format!("map<{}, {}>", Single::Scalar(key).proto_name(), value.proto_name()),
        };

        let deprecated = if f.deprecated { " [deprecated = true]" } else { "" };
        let mut notes = vec![f.ty.to_string()];
        if f.optional {
            notes.push("optional field".into());
        }

        if let Some(d) = &f.default {
            notes.push(format!("default {}", novafile_text::flow_string(d)));
        }

        let _ = writeln!(w, "  {ty} {} = {number}{deprecated}; // {}", ident(&f.name), notes.join("; "));
    }

    w.push_str("}\n");
    Ok(())
}

/// Write a Protobuf `enum` for a NOVA enum without payloads. Value 0 is the
/// `…_UNSPECIFIED` placeholder; variant `i` gets number `i + 1`.
fn unit_enum(w: &mut String, name: &str, vs: &[VariantDef]) {
    let _ = writeln!(w, "enum {} {{", ident(name));
    let _ = writeln!(w, "  {} = 0;", enum_value_name(name, "unspecified"));
    for (i, v) in vs.iter().enumerate() {
        let _ = writeln!(w, "  {} = {}; // {}", enum_value_name(name, &v.name), i + 1, v.name);
    }

    w.push_str("}\n");
}

/// Write a message holding a single `oneof` for a NOVA enum with payloads;
/// variant `i` gets field number `i + 1`, unit variants carry
/// `google.protobuf.Empty`.
fn union(w: &mut String, schema: &Schema, name: &str, vs: &[VariantDef]) -> Result<(), String> {
    let _ = writeln!(w, "message {} {{", ident(name));
    let _ = writeln!(w, "  oneof {} {{", oneof_name(vs));
    for (i, v) in vs.iter().enumerate() {
        let single = classify_payload(schema, name, v)?;
        let note = match &v.payload {
            Some(t) => format!("{}({t})", v.name),
            None => format!("{} (unit variant)", v.name),
        };

        let _ = writeln!(w, "    {} {} = {}; // {note}", single.proto_name(), ident(&v.name), i + 1);
    }

    w.push_str("  }\n}\n");
    Ok(())
}
